      </div>
    `;

    mod.scanStudentWorkByStatus(document);

    expect(createStudentWorkButton).toHaveBeenCalledTimes(1);
    expect(document.querySelectorAll('.cqd-download-btn[data-cqd-sw-bs="true"]')).toHaveLength(1);
